begin;
\ir batch_2_fixture.sql
set local role authenticated;
select pg_temp.assert_true(public.user_owns_business((select id from batch2_ids where key='business')),'owner owns own business');
select pg_temp.assert_true(not public.is_business_member((select id from batch2_ids where key='other_business')),'owner denied other business');
select set_config('request.jwt.claim.sub',(select id::text from batch2_ids where key='manager_user'),true);
select pg_temp.assert_true(not private.has_business_permission((select id from batch2_ids where key='business'),'owner_app'),'employee denied owner contract');
select pg_temp.assert_true(not private.has_business_permission((select id from batch2_ids where key='business'),'view_camera_events'),'manager denied Vision default');
select pg_temp.assert_true(not private.has_business_permission((select id from batch2_ids where key='business'),'view_finance'),'manager denied finance default');
select pg_temp.assert_true((select count(*) from public.business_members where user_id=(select id from batch2_ids where key='owner'))=0,'manager cannot read owner administration record');
select pg_temp.assert_true((select count(*) from public.business_members where business_id=(select id from batch2_ids where key='other_business'))=0,'manager cross-business membership read denied');
select pg_temp.denied(format('select public.set_trexven_employee_permission(%L,''override_price'',true)',(select id from batch2_ids where key='manager')));
select pg_temp.denied(format('select public.update_trexven_employee(%L,''Staff'',null,null,''owner'',''active'')',(select id from batch2_ids where key='sales')));
select pg_temp.denied(format('select public.update_trexven_employee(%L,''Staff'',null,null,''inventory_employee'',''active'')',(select id from batch2_ids where key='sales')));
select pg_temp.denied(format('update public.business_members set permissions=''{"override_price":true}'' where business_id=%L',(select id from batch2_ids where key='business')));
select pg_temp.assert_true(not has_table_privilege('authenticated','public.products','TRUNCATE'),'truncate grant removed');
select pg_temp.assert_true(not has_function_privilege('anon','public.submit_trexven_sale(uuid,uuid,uuid,numeric,text,jsonb,boolean)','EXECUTE'),'anon RPC denied');
select pg_temp.assert_true(not has_function_privilege('authenticated','private.process_trexven_sale(uuid,uuid,numeric,text,jsonb,boolean,uuid)','EXECUTE'),'private core not exposed');
select set_config('request.jwt.claim.sub','',true);
select pg_temp.assert_true(not public.is_business_member((select id from batch2_ids where key='business')),'missing authentication denied');
reset role;
select set_config('request.jwt.claim.sub',(select id::text from batch2_ids where key='owner'),true);
set local role authenticated;
select public.set_trexven_employee_permission((select id from batch2_ids where key='manager'),'override_price',true);
select set_config('request.jwt.claim.sub',(select id::text from batch2_ids where key='manager_user'),true);
select pg_temp.assert_true(private.has_business_permission((select id from batch2_ids where key='business'),'override_price'),'explicit manager grant');
select set_config('request.jwt.claim.sub',(select id::text from batch2_ids where key='owner'),true);
select public.set_trexven_employee_permission((select id from batch2_ids where key='manager'),'override_price',false);
select set_config('request.jwt.claim.sub',(select id::text from batch2_ids where key='manager_user'),true);
select pg_temp.assert_true(not private.has_business_permission((select id from batch2_ids where key='business'),'override_price'),'revocation effective');
select set_config('request.jwt.claim.sub',(select id::text from batch2_ids where key='owner'),true);
select public.set_trexven_employee_permission((select id from batch2_ids where key='manager'),'complete_sales',false);
select set_config('request.jwt.claim.sub',(select id::text from batch2_ids where key='manager_user'),true);
select pg_temp.assert_true(not private.has_business_permission((select id from batch2_ids where key='business'),'complete_sales'),'explicit denial overrides role default');
select set_config('request.jwt.claim.sub',(select id::text from batch2_ids where key='owner'),true);
select public.set_trexven_employee_permission((select id from batch2_ids where key='sales'),'pos_access',false);
select set_config('request.jwt.claim.sub',(select id::text from batch2_ids where key='sales_user'),true);
select pg_temp.denied(format('select public.record_trexven_sale(%L,%L,1,10)',(select id from batch2_ids where key='business'),(select id from batch2_ids where key='product')));
reset role;
select set_config('request.jwt.claim.sub',(select id::text from batch2_ids where key='owner'),true);
update public.employees set status='suspended' where id=(select id from batch2_ids where key='manager');
select set_config('request.jwt.claim.sub',(select id::text from batch2_ids where key='manager_user'),true);
set local role authenticated;
select pg_temp.assert_true(not public.is_business_member((select id from batch2_ids where key='business')),'suspended employee excluded despite membership');
select pg_temp.assert_true((select count(*) from public.products where id=(select id from batch2_ids where key='product'))=0,'suspended employee read denied');
reset role;
select 'Authorization assertions completed (only if executed successfully in isolation)' as result;
rollback;
